/// `tools/apply_layout_tool.py`.
struct LayoutApplyPayload: Codable, Hashable, Sendable {
    var preset: String
    /// Members outside the contract, kept as sent.
    var extras: [String: JSONValue] = [:]

    enum CodingKeys: String, CodingKey, CaseIterable {
        case preset
    }
}

extension LayoutApplyPayload {
    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.preset = try container.decode(String.self, forKey: .preset)
        self.extras = try decoder.extraValues(excluding: Set(CodingKeys.allCases.map(\.stringValue)))
    }

    func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(self.preset, forKey: .preset)
        try encoder.encodeExtras(self.extras, excluding: Set(CodingKeys.allCases.map(\.stringValue)))
    }
}

