/// the pinned `plugin.json` declaration judged on this host; `sentence` names what is missing (empty when
/// present or unknown).
struct OnboardingCatalogPlugin: Codable, Hashable, Sendable {
    var name: String
    var title: String
    var description: String
    var tier: CatalogTier
    var platforms: [String]
    var appState: CatalogAppState
    var sentence: String

    enum CodingKeys: String, CodingKey {
        case name
        case title
        case description
        case tier
        case platforms
        case appState = "app_state"
        case sentence
    }
}

/// `created` is false when an existing setup profile was found (and returned untouched).
struct OnboardingEnsureSetupProfileResult: Codable, Hashable, Sendable {
    var name: String
    var path: String
    var created: Bool
    var role: String?
}

struct OnboardingResetSetupProfileResult: Codable, Hashable, Sendable {
    var name: String
    var path: String
    var reset: Bool?
}

/// One unanswered server→client request (`server_requests.Request.snapshot`); the reconnecting client
/// re-delivers it to its request handlers.
struct OpenRequestEntry: Codable, Hashable, Sendable {
    var id: String
    var method: String
    var params: [String: JSONValue]
}

struct OptionalProjectResult: Codable, Hashable, Sendable {
    var project: ProjectInfo?
}
